function createHashMap() {
  const SIZE = 8
  const buckets = Array.from({ length: SIZE }, () => [])
  const hash = (key) => {
    let h = 0
    for (const ch of String(key)) h = (h * 31 + ch.charCodeAt(0)) % SIZE
    return h
  }
  const find = (key) => buckets[hash(key)].find((e) => e[0] === key)
  return {
    set(key, value) {
      const e = find(key)
      if (e) e[1] = value
      else buckets[hash(key)].push([key, value])
    },
    get(key) {
      const e = find(key)
      return e ? e[1] : undefined
    },
    has(key) {
      return !!find(key)
    },
    delete(key) {
      const b = buckets[hash(key)]
      const i = b.findIndex((e) => e[0] === key)
      if (i === -1) return false
      b.splice(i, 1)
      return true
    },
  }
}

